import { unstable_cache } from 'next/cache';

// Simulate a database with random product data
const getProductsFromDB = async () => {
  // Simulate network delay
  await new Promise((resolve) => setTimeout(resolve, 100));

  return [
    { id: '1', name: 'Ergonomic Chair', price: Math.floor(Math.random() * 100) + 200, stock: Math.floor(Math.random() * 50) },
    { id: '2', name: 'Standing Desk', price: Math.floor(Math.random() * 200) + 400, stock: Math.floor(Math.random() * 30) },
    { id: '3', name: 'Monitor Arm', price: Math.floor(Math.random() * 50) + 100, stock: Math.floor(Math.random() * 100) },
    { id: '4', name: 'Mechanical Keyboard', price: Math.floor(Math.random() * 50) + 150, stock: Math.floor(Math.random() * 20) },
  ];
};

export const getCachedProducts = unstable_cache(
  async () => {
    return await getProductsFromDB();
  },
  ['products'], // Key parts
  { tags: ['products'] } // Tags for invalidation
);

// Mock database
let products = [
  { id: '1', name: 'Ergonomic Chair', price: 299, stock: 45, lastUpdated: new Date().toISOString() },
  { id: '2', name: 'Standing Desk', price: 499, stock: 25, lastUpdated: new Date().toISOString() },
  { id: '3', name: 'Monitor Arm', price: 129, stock: 80, lastUpdated: new Date().toISOString() },
  { id: '4', name: 'Mechanical Keyboard', price: 159, stock: 15, lastUpdated: new Date().toISOString() },
];

export const getProductsRaw = async () => {
  // Simulate slow database query
  await new Promise((resolve) => setTimeout(resolve, 1500));
  return [...products];
};

export const updateProductsMock = () => {
  // Simulate upstream changes (e.g. price updates)
  products = products.map(p => ({
    ...p,
    price: Math.floor(Math.random() * 500) + 100,
    stock: Math.floor(Math.random() * 100),
    lastUpdated: new Date().toISOString()
  }));
  return products;
};

import { unstable_cache } from 'next/cache';
import { getProductsRaw } from './data';

export const getCachedProducts = unstable_cache(
  async () => {
    return await getProductsRaw();
  },
  ['products'],
  { tags: ['products'] }
);

import { getCachedProducts } from '@/lib/products';
import { updateProductsMock } from '@/lib/data';
import { revalidateTag } from 'next/cache';

export default async function Page() {
  const products = await getCachedProducts();

  async function syncCatalog() {
    'use server';
    // Simulate syncing with upstream (e.g. ERP/PIM)
    // This updates the underlying data source
    updateProductsMock();

    // Invalidate the cache to reflect changes
    revalidateTag('products');
  }

  return (
    <div className="p-8 max-w-4xl mx-auto">
      <div className="flex justify-between items-center mb-8">
        <h1 className="text-3xl font-bold">Product Catalog</h1>
        <form action={syncCatalog}>
          <button 
            type="submit" 
            className="bg-blue-600 hover:bg-blue-700 text-white font-medium px-4 py-2 rounded transition-colors"
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {products.map((p: any) => (
          <div key={p.id} className="border border-gray-200 p-6 rounded-lg shadow-sm hover:shadow-md transition-shadow">
            <div className="flex justify-between items-start mb-2">
              <h2 className="text-xl font-semibold text-gray-900">{p.name}</h2>
              <span className={`px-2 py-1 text-xs font-semibold rounded ${p.stock > 0 ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                {p.stock > 0 ? 'In Stock' : 'Out of Stock'}
              </span>
            </div>
            <p className="text-2xl font-bold text-gray-900 mb-4">${p.price}</p>
            <div className="flex justify-between items-end text-sm text-gray-500">
              <span>Stock: {p.stock} units</span>
              <span>Updated: {new Date(p.lastUpdated).toLocaleTimeString()}</span>
            </div>
          </div>
        ))}
      </div>

      <p className="mt-8 text-center text-gray-500 text-sm">
        Catalog data is cached. Use the "Sync" button to refresh from upstream sources.
      </p>
    </div>
  );
}

import fs from 'fs/promises';
import path from 'path';

const DATA_FILE = path.join(process.cwd(), 'products.json');

// Simulate slow database query for reads
export const getProductsRaw = async () => {
  // Simulate network delay for the read operation
  await new Promise((resolve) => setTimeout(resolve, 1500));

  try {
    const data = await fs.readFile(DATA_FILE, 'utf-8');
    return JSON.parse(data);
  } catch (error) {
    console.error("Error reading products:", error);
    return [];
  }
};

// Fast update to simulate upstream sync
export const updateProductsMock = async () => {
  try {
    const data = await fs.readFile(DATA_FILE, 'utf-8');
    const products = JSON.parse(data);

    const newData = products.map((p: any) => ({
      ...p,
      price: Math.floor(Math.random() * 500) + 50,
      stock: Math.floor(Math.random() * 100),
      lastUpdated: new Date().toISOString()
    }));

    await fs.writeFile(DATA_FILE, JSON.stringify(newData, null, 2));
    return newData;
  } catch (error) {
    console.error("Error updating products:", error);
    return [];
  }
};

