import { getCachedProducts } from '@/lib/products';
import { updateProductsMock } from '@/lib/data';
import { revalidateTag } from 'next/cache';

// Force dynamic behavior where needed, but cached data is used primarily
export const dynamic = 'force-dynamic';

export default async function Page() {
  const products = await getCachedProducts();

  async function syncCatalog() {
    'use server';
    // Simulate syncing with upstream (e.g. ERP/PIM)
    // This updates the underlying data source
    await updateProductsMock();

    // Invalidate the cache to reflect changes
    revalidateTag('products');
  }

  return (
    <div className="min-h-screen bg-gray-50 p-8 font-sans">
      <div className="max-w-4xl mx-auto">
        <header className="flex justify-between items-center mb-8 bg-white p-6 rounded-lg shadow-sm">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Admin Product Catalog</h1>
            <p className="text-sm text-gray-500 mt-1">Manage pricing and inventory</p>
          </div>

          <form action={syncCatalog}>
            <button 
              type="submit" 
              className="bg-blue-600 hover:bg-blue-700 text-white font-medium px-6 py-3 rounded-md transition-all flex items-center gap-2 shadow-sm hover:shadow active:scale-95"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" viewBox="0 0 16 16">
                <path fillRule="evenodd" d="M8 3a5 5 0 1 0 4.546 2.914.5.5 0 0 1 .908-.417A6 6 0 1 1 8 2v1z"/>
                <path d="M8 4.466V.534a.25.25 0 0 1 .41-.192l2.36 1.966c.12.1.12.284 0 .384L8.41 4.658A.25.25 0 0 1 8 4.466z"/>
              </svg>
              Sync Latest Catalog
            </button>
          </form>
        </header>

        <div className="grid grid-cols-1 gap-4">
          <div className="bg-white rounded-lg shadow-sm overflow-hidden border border-gray-200">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-gray-50 text-gray-600 text-sm font-semibold border-b border-gray-200">
                  <th className="px-6 py-4">Product Name</th>
                  <th className="px-6 py-4">Status</th>
                  <th className="px-6 py-4 text-right">Price</th>
                  <th className="px-6 py-4 text-right">Stock</th>
                  <th className="px-6 py-4 text-right">Last Sync</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {products.map((p: any) => (
                  <tr key={p.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4 font-medium text-gray-900">{p.name}</td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                        p.stock > 20 
                          ? 'bg-green-100 text-green-800' 
                          : p.stock > 0 
                            ? 'bg-yellow-100 text-yellow-800' 
                            : 'bg-red-100 text-red-800'
                      }`}>
                        {p.stock > 0 ? (p.stock > 20 ? 'In Stock' : 'Low Stock') : 'Out of Stock'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right font-semibold text-gray-900">
                      ${p.price.toLocaleString()}
                    </td>
                    <td className="px-6 py-4 text-right text-gray-600">
                      {p.stock}
                    </td>
                    <td className="px-6 py-4 text-right text-xs text-gray-400 font-mono">
                      {new Date(p.lastUpdated).toLocaleTimeString()}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div className="mt-8 text-center">
          <p className="text-gray-500 text-sm bg-blue-50 inline-block px-4 py-2 rounded-full border border-blue-100">
            ℹ️ Catalog data is cached for performance. Syncing updates from upstream PIM/ERP.
          </p>
        </div>
      </div>
    </div>
  );
}

